                        </span>
                    )}
                    {infoCount > 0 && (
                        <span className="inline-flex items-center gap-1 bg-[#E3F2FD] px-2 py-1 text-xs font-bold text-[#1565C0]">
                            {infoCount} info
                        </span>
                    )}
                </div>

                <div className="flex gap-0 border-2 border-black">
                    {filters.map((f) => (
                        <button
                            key={f.key}
                            onClick={() => setFilter(f.key)}
