                        >
                            {f.label}
                        </button>
                    ))}
                </div>

                {filtered.length === 0 ? (
                    <div className="flex flex-col items-center gap-3 py-16 text-center">
                        <CheckCircle2 className="size-12 text-[#2E7D32]" />
